arguments.script:
System.Collections.IEnumerator Check(){
GameMenuUI.Testing=true;GameMenuUI.PreferencePrefix="Goombas.Campaign.TEST.Orbit."+System.Guid.NewGuid()+".";
var rigs=UnityEngine.Object.FindObjectsOfType<OrbitRidePlatform>();var selected=new System.Collections.Generic.List<OrbitRidePlatform>();foreach(var o in rigs)if(o.center.x>45)selected.Add(o);
if(selected.Count!=8)throw new System.Exception("Expected eight platforms, got "+selected.Count);
var start=new UnityEngine.Vector2[8];for(int i=0;i<8;i++)start[i]=selected[i].transform.position;
yield return new UnityEngine.WaitForSeconds(1);
for(int i=0;i<8;i++){var o=selected[i];if(UnityEngine.Vector2.Distance(start[i],o.transform.position)<.5f)throw new System.Exception("No circular movement");if(UnityEngine.Mathf.Abs(UnityEngine.Vector2.Distance(o.transform.position,o.center)-1.6f)>.04f)throw new System.Exception("Wrong radius");if(UnityEngine.Quaternion.Angle(o.transform.rotation,UnityEngine.Quaternion.identity)>.01f)throw new System.Exception("Tread tilts");}
var report="PASS actual Play: eight platforms, two centers (50,2.4)/(58,2.4), radius 1.6m; each moved >.5m in 1s; platform rotation remains horizontal. Period 7s. Passenger/full traversal NOT RUN.";
System.IO.File.WriteAllText("scripts/third-orbit-check.txt",System.DateTime.UtcNow.ToString("O")+"\n"+report);UnityEngine.Debug.Log(report);
} return Check();
